// Investor check (C7): group InvestorCheck.rounds into a market map, one entry
// per company (the startup first, then each competitor), with deduped backers.

import type { Competitor, Conflict, EntityRef, InvestorCheck, Round } from "./types";

export interface Backer {
  investor: EntityRef;
  led: boolean; // led at least one of this company's rounds
}

export interface MarketEntry {
  company: EntityRef;
  competitor: Competitor | null; // null for the startup itself (or an unknown company)
  rounds: Round[]; // dated rounds newest first, then undated
  backers: Backer[]; // leads first, then by name
}

export function marketMap(check: InvestorCheck): MarketEntry[] {
  const byCompany = new Map<string, Round[]>();
  for (const r of check.rounds) {
    const list = byCompany.get(r.company_id) ?? [];
    list.push(r);
    byCompany.set(r.company_id, list);
  }
  const entry = (company: EntityRef, competitor: Competitor | null): MarketEntry => {
    const rounds = sortRounds(byCompany.get(company.id) ?? []);
    byCompany.delete(company.id);
    return { company, competitor, rounds, backers: backersOf(rounds) };
  };

  const entries = [
    entry(check.company, null),
    ...check.competitors.map((c) => entry(c.company, c)),
  ];
  // Rounds of a company that is neither the startup nor a listed competitor: keep them.
  for (const [id, rounds] of byCompany) {
    const sorted = sortRounds(rounds);
    entries.push({
      company: { id, name: "Other company", type: "Company", description: null },
      competitor: null,
      rounds: sorted,
      backers: backersOf(sorted),
    });
  }
  return entries;
}

export function sortRounds(rounds: Round[]): Round[] {
  return [...rounds].sort((a, b) => {
    if (a.date && b.date) return b.date.localeCompare(a.date);
    if (a.date) return -1;
    if (b.date) return 1;
    return 0;
  });
}

export function backersOf(rounds: Round[]): Backer[] {
  const map = new Map<string, Backer>();
  for (const r of rounds) {
    for (const ri of r.investors) {
      const prev = map.get(ri.investor.id);
      map.set(ri.investor.id, { investor: ri.investor, led: Boolean(prev?.led || ri.is_lead) });
    }
  }
  return [...map.values()].sort(
    (a, b) => Number(b.led) - Number(a.led) || a.investor.name.localeCompare(b.investor.name),
  );
}

/** Undated rounds without a label are A7's "backers without round details". */
export function roundTitle(r: Round): string {
  if (!r.label && !r.date && !r.amount_text) return "Round details unknown";
  return r.label ?? "Round";
}

/** The conflict from the investor's side of the table. */
export function investorConflictText(c: Conflict, startupName: string): string {
  if (c.kind === "BOARD") {
    return c.via_person
      ? `${c.via_person.name} sits on the board of ${c.competitor.name}, which competes with ${startupName}`
      : `You have a board seat at ${c.competitor.name}, which competes with ${startupName}`;
  }
  return `${c.competitor.name} is in your portfolio and competes with ${startupName}`;
}

import assert from "node:assert/strict";
import { readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { test } from "node:test";
import { fileURLToPath } from "node:url";

import { backersOf, investorConflictText, marketMap, roundTitle, sortRounds } from "./check.ts";
import type { EntityRef, InvestorCheck, Round } from "./types.ts";

const ref = (id: string, type = "Organization"): EntityRef => ({ id, name: id, type, description: null });
const round = (over: Partial<Round>): Round => ({
  id: Math.random().toString(36),
  company_id: "x",
  label: null,
  date: null,
  amount_text: null,
  amount_eur: null,
  investors: [],
  sources: [],
  ...over,
});

test("sortRounds: newest dated first, undated last", () => {
  const rs = [round({ id: "u" }), round({ id: "old", date: "2024" }), round({ id: "new", date: "2026-04-14" })];
  assert.deepEqual(sortRounds(rs).map((r) => r.id), ["new", "old", "u"]);
});

test("backersOf dedupes, a lead anywhere wins, leads first", () => {
  const rs = [
    round({ investors: [{ investor: ref("Tesi"), is_lead: false }, { investor: ref("NIF"), is_lead: true }] }),
    round({ investors: [{ investor: ref("Tesi"), is_lead: null }, { investor: ref("Angel"), is_lead: null }] }),
  ];
  assert.deepEqual(
    backersOf(rs).map((b) => [b.investor.id, b.led]),
    [["NIF", true], ["Angel", false], ["Tesi", false]],
  );
});

test("roundTitle", () => {
  assert.equal(roundTitle(round({})), "Round details unknown");
  assert.equal(roundTitle(round({ label: "Series A" })), "Series A");
  assert.equal(roundTitle(round({ date: "2026" })), "Round");
});

test("investorConflictText", () => {
  const c = { kind: "PORTFOLIO" as const, competitor: ref("Aavuus", "Company"), via_person: null, sources: [] };
  assert.equal(investorConflictText(c, "Stendr"), "Aavuus is in your portfolio and competes with Stendr");
  assert.equal(
    investorConflictText({ ...c, kind: "BOARD", via_person: ref("Jane", "Person") }, "Stendr"),
    "Jane sits on the board of Aavuus, which competes with Stendr",
  );
});

test("marketMap on every investor-check fixture keeps every round", () => {
  const dir = join(dirname(fileURLToPath(import.meta.url)), "../../contracts/fixtures/models");
  const files = readdirSync(dir).filter((f) => f.startsWith("investor_check_"));
  assert.ok(files.length > 0);
  for (const f of files) {
    const check = JSON.parse(readFileSync(join(dir, f), "utf8")) as InvestorCheck;
    const map = marketMap(check);
    assert.equal(map[0].company.id, check.company.id, "startup first");
    assert.equal(map[0].competitor, null);
    assert.equal(
      map.reduce((n, e) => n + e.rounds.length, 0),
      check.rounds.length,
      `${f}: no round dropped`,
    );
  }
});

"use client";

// Investor check (C7): verdict first (conflict or not), then the market map:
// the startup and each competitor with who backed it and its round history.

import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";

import { SourceBadges } from "@/components/SourceBadge";
import { ApiError, checkInvestor } from "@/lib/api";
import { investorConflictText, marketMap, roundTitle, type MarketEntry } from "@/lib/check";
import { prettyEnum } from "@/lib/format";
import { founderPath } from "@/lib/routes";
import { formatSourceDate } from "@/lib/sources";
import type { InvestorCheck, Round } from "@/lib/types";

type Load =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean }
  | { status: "ready"; check: InvestorCheck };

export function InvestorCheckView({ investorId, companyId }: { investorId: string; companyId: string }) {
  const [load, setLoad] = useState<Load>({ status: "loading" });
  const abort = useRef<AbortController | null>(null);

  const run = useCallback(async () => {
    abort.current?.abort();
    const ctrl = new AbortController();
    abort.current = ctrl;
    setLoad({ status: "loading" });
    try {
      const check = await checkInvestor({ investor_id: investorId, company_id: companyId }, ctrl.signal);
      if (!ctrl.signal.aborted) setLoad({ status: "ready", check });
    } catch (err) {
      if (ctrl.signal.aborted) return;
      setLoad({
        status: "error",
        message: err instanceof ApiError ? err.message : "Something went wrong.",
        notFound: err instanceof ApiError && err.status === 404,
      });
    }
  }, [investorId, companyId]);

  useEffect(() => {
    void run();
    return () => abort.current?.abort();
  }, [run]);

  if (load.status === "loading") {
    return (
      <div aria-busy="true" aria-live="polite">
        <p className="label text-muted">Investor check</p>
        <div className="mt-4 h-20 w-2/3 max-w-xl animate-pulse bg-surface" />
        <p className="mt-8 max-w-xl text-muted">
          Comparing your portfolio with this startup&apos;s competitors in Cala, and pulling who
          backed each of them.
        </p>
      </div>
    );
  }
  if (load.status === "error") {
    return (
      <div className="max-w-xl">
        <p className="label text-muted">Investor check</p>
        <h1 className="display mt-4 text-5xl">
          {load.notFound ? "We couldn't check that pair." : "The check didn't load."}
        </h1>
        <p className="mt-6 border-l-2 border-foreground pl-3">{load.message}</p>
        <div className="mt-8 flex gap-3">
          {!load.notFound && (
            <button type="button" className="btn-primary" onClick={() => void run()}>
              Try again
            </button>
          )}
          <Link href="/" className="btn-ghost h-[47px]">
            Search again
          </Link>
        </div>
      </div>
    );
  }

  const { check } = load;
  const { investor, company, conflicts } = check;
  const map = marketMap(check);
  const facts = [
    company.stage,
    company.country,
    ...company.industries.map(prettyEnum),
    company.total_funding_text && `${company.total_funding_text} raised`,
  ].filter(Boolean) as string[];

  return (
    <div>
      <header>
        <p className="label text-muted">Investor check · as {investor.name}</p>
        <h1 className="display mt-4 text-6xl md:text-8xl">{company.name}</h1>
        {facts.length > 0 && (
          <p className="label mt-6 flex flex-wrap gap-x-4 gap-y-1 text-muted">
            {facts.map((f) => (
              <span key={f}>{f}</span>
            ))}
          </p>
        )}
        {company.description && <p className="mt-4 max-w-2xl text-lg leading-snug">{company.description}</p>}
        <div className="mt-4 flex flex-wrap items-center gap-4">
          <SourceBadges sources={company.sources} />
          <Link href={founderPath(company.id)} className="text-sm underline underline-offset-4">
            Flip: see {company.name}&apos;s founder view
          </Link>
        </div>
      </header>

      {conflicts.length > 0 ? (
        <section className="mt-16 bg-press px-6 py-10 text-background md:px-10 md:py-14" aria-labelledby="verdict">
          <p className="label text-sage">Verdict</p>
          <h2 id="verdict" className="display mt-4 text-5xl md:text-7xl">
            Conflict.
          </h2>
          <ul className="mt-8 space-y-6">
            {conflicts.map((c, i) => (
              <li key={`${c.competitor.id}-${c.kind}-${i}`}>
                <p className="max-w-3xl text-xl leading-snug">{investorConflictText(c, company.name)}</p>
                <div className="mt-2">
                  <SourceBadges sources={c.sources} max={3} />
                </div>
              </li>
            ))}
          </ul>
        </section>
      ) : (
        <section className="mt-16 border-l-4 border-accent py-2 pl-6" aria-labelledby="verdict">
          <p className="label text-muted">Verdict</p>
          <h2 id="verdict" className="display mt-3 text-5xl md:text-6xl">
            No conflict found.
          </h2>
          <p className="mt-4 max-w-2xl text-muted">
            None of {company.name}&apos;s {check.competitors.length} competitors is in {investor.name}&apos;s
            portfolio in Cala, and no board links were found. Cala&apos;s portfolio data can be
            incomplete, so check anything that looks off.
          </p>
        </section>
      )}

      <section className="mt-20" aria-labelledby="map-heading">
        <p className="label text-muted">Market map · {check.competitors.length} competitors</p>
        <h2 id="map-heading" className="display mt-3 text-5xl md:text-6xl">
          Who backed the rivals
        </h2>
        <p className="mt-4 max-w-2xl text-muted">
          {company.name} and its competitors, with every investor Cala links to them and their
          round history. Leads are marked; your fund is highlighted.
        </p>
        <div className="mt-8">
          {map.map((e) => (
            <MarketCard key={e.company.id} entry={e} isStartup={e.company.id === company.id} investorId={investor.id} />
          ))}
        </div>
      </section>
    </div>
  );
}

function MarketCard({ entry, isStartup, investorId }: { entry: MarketEntry; isStartup: boolean; investorId: string }) {
  const { company, competitor, rounds, backers } = entry;
  const c = competitor?.company;
  const meta = c ? [c.stage, c.country].filter(Boolean).join(" · ") : "";
  return (
    <article className="grid gap-x-10 gap-y-4 border-t border-line py-8 md:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">
      <div>
        <p className="label text-muted">{isStartup ? "The startup" : competitor ? "Competitor" : "Other"}</p>
        <h3 className="mt-2 text-2xl font-medium tracking-tight">{company.name}</h3>
        {meta && <p className="label mt-2 text-muted">{meta}</p>}
        {competitor && (
          <p className="mt-3 text-sm leading-snug">
            {competitor.reason} <span className="label ml-1 text-muted">AI judgement</span>
          </p>
        )}
        {c && c.sources.length > 0 && (
          <div className="mt-3">
            <SourceBadges sources={c.sources} />
          </div>
        )}
      </div>

      <div>
        <p className="label">Backed by · {backers.length}</p>
        {backers.length === 0 ? (
          <p className="mt-2 text-sm text-muted">No investors in Cala.</p>
        ) : (
          <ul className="mt-2 flex flex-wrap gap-1.5">
            {backers.map((b) => {
              const you = b.investor.id === investorId;
              return (
                <li
                  key={b.investor.id}
                  className={`rounded-[5px] border px-2 py-1 text-sm ${
                    you ? "border-foreground bg-accent font-medium" : "border-line"
                  }`}
                >
                  {b.investor.name}
                  {b.led && <span className="label ml-1.5">Lead</span>}
                  {you && <span className="label ml-1.5">You</span>}
                </li>
              );
            })}
          </ul>
        )}

        <p className="label mt-6">Rounds · {rounds.length}</p>
        {rounds.length === 0 ? (
          <p className="mt-2 text-sm text-muted">No rounds in Cala.</p>
        ) : (
          <ul className="mt-2 divide-y divide-line border-y border-line">
            {rounds.map((r) => (
              <RoundRow key={r.id} round={r} investorId={investorId} />
            ))}
          </ul>
        )}
      </div>
    </article>
  );
}

function RoundRow({ round, investorId }: { round: Round; investorId: string }) {
  const date = formatSourceDate(round.date);
  const title = roundTitle(round);
  const unknown = title === "Round details unknown";
  return (
    <li className="py-3 text-sm">
      <p className="flex flex-wrap items-baseline gap-x-3">
        <span className={unknown ? "text-muted italic" : "font-medium"}>{title}</span>
        {date && <span className="text-muted">{date}</span>}
        {round.amount_text && <span>{round.amount_text}</span>}
      </p>
      {round.investors.length > 0 && (
        <p className="mt-1 text-muted">
          {round.investors.map((ri, i) => (
            <span key={ri.investor.id}>
              {i > 0 && ", "}
              <span className={ri.investor.id === investorId ? "font-medium text-foreground" : ""}>
                {ri.investor.name}
              </span>
              {ri.is_lead && " (lead)"}
            </span>
          ))}
        </p>
      )}
      <div className="mt-1.5">
        <SourceBadges sources={round.sources} />
      </div>
    </li>
  );
}

import { Suspense } from "react";

import { InvestorCheckView } from "@/components/InvestorCheckView";

type Params = PageProps<"/check/[investorId]/[companyId]">["params"];

export default function CheckPage({ params }: { params: Params }) {
  return (
    <Suspense fallback={null}>
      <Check params={params} />
    </Suspense>
  );
}

async function Check({ params }: { params: Params }) {
  const { investorId, companyId } = await params;
  return (
    <InvestorCheckView key={`${investorId}/${companyId}`} investorId={investorId} companyId={companyId} />
  );
}

