// Source badge: rank + date + link, shown next to every claim (CLAUDE.md §6, C4).
// No client JS: <details> handles "+N more", so it works in server components too.

import { formatSourceDate, rankLabel, safeUrl, sortSources } from "@/lib/sources";
import type { Source, SourceRank } from "@/lib/types";

// DESIGN.md allows one accent, so reliability is shown by weight, not hue:
// green tints for first-hand sources, ink outline for press, faint for the rest.
const RANK_STYLE: Record<SourceRank, string> = {
  PRIMARY: "border-moss bg-echo text-foreground",
  FILING: "border-moss bg-surface text-foreground",
  PRESS: "border-foreground/40 bg-background text-foreground",
  AGGREGATOR: "border-line bg-background text-muted",
  UNKNOWN: "border-dashed border-line bg-background text-muted",
};

const BASE =
  "inline-flex max-w-full items-center gap-1.5 rounded-[5px] border px-1.5 py-0.5 text-xs leading-4 whitespace-nowrap";

export function SourceBadge({ source }: { source: Source }) {
  const date = formatSourceDate(source.date);
  const href = safeUrl(source.url);
  const title = [source.name, source.date, source.url].filter(Boolean).join(" · ");
  const body = (
    <>
      <span className="label">{rankLabel(source.rank)}</span>
      {date && <span className="opacity-75">{date}</span>}
      {href && <span aria-hidden="true">↗</span>}
    </>
  );

  if (!href) {
    return (
      <span className={`${BASE} ${RANK_STYLE[source.rank]}`} title={title}>
        {body}
      </span>
    );
  }
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      title={title}
      aria-label={`${rankLabel(source.rank)} source: ${source.name}${date ? `, ${date}` : ""} (opens in a new tab)`}
      className={`${BASE} ${RANK_STYLE[source.rank]} hover:border-foreground`}
    >
      {body}
    </a>
  );
}

/**
 * All sources of one claim: the most reliable first, the rest behind "+N".
 * Renders "No source" when the list is empty, so a missing source is visible.
 */
export function SourceBadges({ sources, max = 1 }: { sources: Source[]; max?: number }) {
  if (sources.length === 0) {
    return <span className={`${BASE} ${RANK_STYLE.UNKNOWN} italic`}>No source</span>;
  }
  const sorted = sortSources(sources);
  const shown = sorted.slice(0, max);
  const rest = sorted.slice(max);
  return (
    <span className="inline-flex flex-wrap items-center gap-1 align-middle">
      {shown.map((s, i) => (
        <SourceBadge key={`${s.url ?? s.name}-${i}`} source={s} />
      ))}
      {rest.length > 0 && (
        <details className="group inline-block">
          <summary
            className={`${BASE} ${RANK_STYLE.UNKNOWN} cursor-pointer list-none hover:text-foreground [&::-webkit-details-marker]:hidden`}
          >
            <span className="group-open:hidden">+{rest.length}</span>
            <span className="hidden group-open:inline">less</span>
          </summary>
          <span className="mt-1 flex flex-wrap gap-1">
            {rest.map((s, i) => (
              <SourceBadge key={`${s.url ?? s.name}-${i}`} source={s} />
            ))}
          </span>
        </details>
      )}
    </span>
  );
}
// Pure helpers behind the source badge (no React, so they're unit-tested).

import type { Source, SourceRank } from "./types";

const RANK_LABEL: Record<SourceRank, string> = {
  PRIMARY: "Primary",
  FILING: "Filing",
  PRESS: "Press",
  AGGREGATOR: "Aggregator",
  UNKNOWN: "Source",
};

// Most reliable first; OVERVIEW: "prefer primary sources when facts conflict".
const RANK_ORDER: SourceRank[] = ["PRIMARY", "FILING", "PRESS", "AGGREGATOR", "UNKNOWN"];

const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function rankLabel(rank: SourceRank): string {
  return RANK_LABEL[rank] ?? RANK_LABEL.UNKNOWN;
}

/** "2025-10-03" → "3 Oct 2025", "2025-10" → "Oct 2025", "2026" → "2026"; anything else as-is. */
export function formatSourceDate(date: string | null): string | null {
  if (!date) return null;
  const m = /^(\d{4})(?:-(\d{2})(?:-(\d{2}))?)?/.exec(date.trim());
  if (!m) return date;
  const [, y, mo, d] = m;
  const month = mo ? MONTHS[Number(mo) - 1] : undefined;
  if (!month) return y; // no month, or an invalid one
  return d ? `${Number(d)} ${month} ${y}` : `${month} ${y}`;
}

/** Only http(s) links are rendered; anything else is shown as plain text. */
export function safeUrl(url: string | null): string | null {
  if (!url) return null;
  try {
    const u = new URL(url);
    return u.protocol === "http:" || u.protocol === "https:" ? u.href : null;
  } catch {
    return null;
  }
}

/** Best rank first, then newest first. Stable for equal keys; does not mutate. */
export function sortSources(sources: Source[]): Source[] {
  return [...sources].sort((a, b) => {
    const r = RANK_ORDER.indexOf(a.rank) - RANK_ORDER.indexOf(b.rank);
    if (r !== 0) return r;
    return (b.date ?? "").localeCompare(a.date ?? "");
  });
}
"use client";

// Founder report (C5, C6): company header, competitor chips, then the Pitch and
// Skip lists. Removing competitors and pressing "Re-rank" calls
// /api/founder/analyze again with the remaining `competitor_ids`.

import Link from "next/link";
import { useCallback, useEffect, useRef, useState } from "react";

import { ChatPanel } from "@/components/ChatPanel";
import { CompetitorChips } from "@/components/CompetitorChips";
import { AmountField } from "@/components/FundingFit";
import { PitchCard, SkipCard } from "@/components/InvestorCard";
import { SlowNotice } from "@/components/SlowNotice";
import { SourceBadges } from "@/components/SourceBadge";
import { analyzeFounder } from "@/lib/api";
import { describeError } from "@/lib/errors";
import { keptCompetitorIds, prettyEnum } from "@/lib/format";
import { prepPath } from "@/lib/routes";
import type { Company, FounderReport } from "@/lib/types";

// Live reports rank 30-45 investors; the top ones matter, and the Skip list below
// (the conflict) must stay within reach: each card is ~235 px tall.
const PITCH_SHOWN = 5;

type Load =
  | { status: "loading" }
  | { status: "error"; message: string; notFound: boolean; detail: string | null }
  | { status: "ready"; report: FounderReport; reranking: boolean; rerankError: string | null };

export function FounderReportView({
  companyId,
  initialTarget = null,
}: {
  companyId: string;
  initialTarget?: number | null; // ?raise= in the URL (C18)
}) {
  const [load, setLoad] = useState<Load>({ status: "loading" });
  const [removed, setRemoved] = useState<Set<string>>(new Set());
  const [narrowed, setNarrowed] = useState(false); // ranked against a user-edited list
  const [showAllPitch, setShowAllPitch] = useState(false);
  const [target, setTarget] = useState<number | null>(initialTarget); // the founder's raise (B21)
  const abort = useRef<AbortController | null>(null);

  // Fetches and stores a report. State is set only in the promise callbacks, so the initial
  // load can run from an effect; `run` below flips the loading state first, from handlers.
  const fetchReport = useCallback(
    (competitorIds?: string[], raise?: number | null) => {
      abort.current?.abort();
      const ctrl = new AbortController();
      abort.current = ctrl;
      return analyzeFounder(
        {
          company_id: companyId,
          ...(competitorIds ? { competitor_ids: competitorIds } : {}),
          ...(raise ? { target_amount_eur: raise } : {}),
        },
        ctrl.signal,
      ).then(
        (report) => {
          if (ctrl.signal.aborted) return;
          setLoad({ status: "ready", report, reranking: false, rerankError: null });
          setRemoved(new Set());
          setNarrowed(Boolean(competitorIds));
          setShowAllPitch(false);
        },
        (err: unknown) => {
          if (ctrl.signal.aborted) return;
          const e = describeError(err);
          setLoad((prev) =>
            prev.status === "ready" && competitorIds
              ? { ...prev, reranking: false, rerankError: e.message }
              : { status: "error", message: e.message, notFound: e.notFound, detail: e.detail },
          );
        },
      );
    },
    [companyId],
  );

  function run(competitorIds?: string[], raise: number | null = target, keepReport = false) {
    setLoad((prev) =>
      prev.status === "ready" && (competitorIds || keepReport)
        ? { ...prev, reranking: true, rerankError: null }
        : { status: "loading" },
    );
    void fetchReport(competitorIds, raise);
  }

  // A new raise re-ranks against the same competitors, and is kept in the URL (?raise=).
  function applyRaise(raise: number | null) {
    setTarget(raise);
    const url = new URL(window.location.href);
    if (raise) url.searchParams.set("raise", String(raise));
    else url.searchParams.delete("raise");
    window.history.replaceState(null, "", url);
    const current =
      load.status === "ready" && narrowed ? load.report.competitors.map((c) => c.company.id) : undefined;
    run(current, raise, true);
  }

  useEffect(() => {
    void fetchReport(undefined, initialTarget);
    return () => abort.current?.abort();
  }, [fetchReport, initialTarget]);

  if (load.status === "loading") return <LoadingReport />;
  if (load.status === "error") {
    return (
      <div className="max-w-xl">
        <p className="label text-muted">Founder report</p>
        <h1 className="display mt-4 text-5xl">
          {load.notFound ? "We couldn't find that company." : "The report didn't load."}
        </h1>
        <p className="mt-6 border-l-2 border-foreground pl-3">{load.message}</p>
        {load.detail && (
          <details className="mt-3 text-sm text-muted">
            <summary className="cursor-pointer">Technical details</summary>
            <p className="mt-2 font-mono text-xs break-all">{load.detail}</p>
          </details>
        )}
        <div className="mt-8 flex gap-3">
          {!load.notFound && (
            <button type="button" className="btn-primary" onClick={() => void run()}>
              Try again
            </button>
          )}
          <Link href="/" className="btn-ghost h-[47px]">
            Search again
          </Link>
        </div>
      </div>
    );
  }

  const { report, reranking, rerankError } = load;
  const ids = report.competitors.map((c) => c.company.id);
  const kept = keptCompetitorIds(ids, removed);

  return (
    <div>
      <title>{`${report.company.name} · Founder report · PitchSwitch`}</title>
      <ChatPanel
        companyId={report.company.id}
        scope={report.company.name}
        suggestions={[
          "Who are my top 3 investors to pitch, and why?",
          ...(report.skip[0] ? [`Why should I skip ${report.skip[0].investor.name}?`] : []),
          ...(report.pitch[0] ? [`What has ${report.pitch[0].investor.name} led recently?`] : []),
        ]}
      />
      <CompanyHeader company={report.company} />

      <section className="mt-16 border-t border-line pt-8">
        <div className="flex flex-wrap items-baseline justify-between gap-4">
          <div>
            <p className="label">Competitors · {kept.length}</p>
            <p className="mt-2 max-w-xl text-sm text-muted">
              Investors who backed these go on the Skip list. Hover a name to see why it counts;
              remove the ones that don&apos;t, then re-rank.
            </p>
          </div>
          <div className="flex items-center gap-4">
            {narrowed && removed.size === 0 && (
              <button
                type="button"
                disabled={reranking}
                onClick={() => void run()}
                className="text-sm underline underline-offset-4 disabled:opacity-40"
              >
                Reset to all competitors
              </button>
            )}
            {removed.size > 0 && (
              <button
                type="button"
                disabled={reranking}
                onClick={() => void run(kept)}
                className="btn-primary"
              >
                {reranking ? "Re-ranking…" : `Re-rank with ${kept.length}`}
              </button>
            )}
          </div>
        </div>
        {reranking && <SlowNotice />}
        {rerankError && (
          <p className="mt-4 border-l-2 border-foreground pl-3 text-sm">
            Re-ranking failed: {rerankError}
          </p>
        )}
        <div className="mt-6">
          {report.competitors.length === 0 ? (
            <p className="text-muted">
              No direct competitors found in Cala, so no investor has a conflict yet.
            </p>
          ) : (
            <CompetitorChips
              competitors={report.competitors}
              removed={removed}
              disabled={reranking}
              onRemove={(id) => setRemoved((s) => new Set(s).add(id))}
              onRestore={(id) =>
                setRemoved((s) => {
                  const next = new Set(s);
                  next.delete(id);
                  return next;
                })
              }
            />
          )}
        </div>
      </section>

      <section className="mt-12 border-t border-line pt-8" aria-label="Funding amount">
        <AmountField side="founder" value={target} onApply={applyRaise} disabled={reranking} />
        {target !== null && !reranking && ![...report.pitch, ...report.skip].some((s) => s.funding_fit) && (
          <p className="mt-3 text-sm text-muted">
            Fit by round size isn&apos;t available on this server yet; it will show on each card once
            it is.
          </p>
        )}
      </section>

      <div className={`transition-opacity ${reranking ? "opacity-40" : ""}`} aria-busy={reranking}>
        <section className="mt-20" aria-labelledby="pitch-heading">
          <ListHeading
            id="pitch-heading"
            label="Pitch"
            count={report.pitch.length}
            title="Who to pitch"
            hint="Ranked by fit: how often they lead and invest in your space, how recently and actively, warm paths, stage fit and a Nordic or Baltic focus. Open a card to see how its score adds up. None of them backed your competitors."
          />
          {report.skip.length > 0 && (
            <a href="#skip-heading" className="mt-3 inline-block text-sm underline underline-offset-4">
              Jump to the {report.skip.length} to skip ↓
            </a>
          )}
          {report.pitch.length === 0 ? (
            <p className="mt-6 border-t border-line pt-6 text-muted">
              No investors without a conflict found in your space yet.
            </p>
          ) : (
            <>
              <ol className="mt-6">
                {(showAllPitch ? report.pitch : report.pitch.slice(0, PITCH_SHOWN)).map((s, i) => (
                  <li key={s.investor.id}>
                    <PitchCard item={s} rank={i + 1} companyId={report.company.id} companyName={report.company.name} />
                  </li>
                ))}
              </ol>
              {report.pitch.length > PITCH_SHOWN && (
                <button
                  type="button"
                  onClick={() => setShowAllPitch((v) => !v)}
                  className="btn-ghost mt-2 h-10"
                >
                  {showAllPitch ? `Show top ${PITCH_SHOWN}` : `Show all ${report.pitch.length}`}
                </button>
              )}
            </>
          )}
        </section>

        <section className="mt-20" aria-labelledby="skip-heading">
          <ListHeading
            id="skip-heading"
            label="Skip"
            count={report.skip.length}
            title="Who to skip"
            hint="They backed a direct competitor, or one of their people sits on its board. Pitching them means handing your deck to a rival's backer."
          />
          {report.skip.length === 0 ? (
            <p className="mt-6 border-t border-line pt-6 text-muted">
              No conflicts: none of these investors backed your competitors.
            </p>
          ) : (
            <ul className="mt-6">
              {report.skip.map((s) => (
                <li key={s.investor.id}>
                  <SkipCard item={s} companyId={report.company.id} companyName={report.company.name} />
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>
    </div>
  );
}

function ListHeading({
  id,
  label,
  count,
  title,
  hint,
}: {
  id: string;
  label: string;
  count: number;
  title: string;
  hint: string;
